import {
	Accessor,
	createContext,
	createEffect,
	createMemo,
	createSignal,
	JSX,
	on,
	onCleanup,
	onMount,
	ParentProps,
	Setter,
	Show,
	useContext,
} from "solid-js";
import { Portal } from "solid-js/web";

import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { Panel } from "#core/ui-next/components/panel.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { Slot } from "#core/ui-next/components/slot.jsx";
import { useAudio } from "#core/ui-next/services/audio-support.js";
import { FocusManager } from "#core/ui-next/services/focus-manager.js";
import { FocusContextProvider, FocusNavigationRulesMap } from "#core/ui-next/services/focus.js";
import { LayoutModel } from "#core/ui-next/utilities/layout-utilities.js";

const DropdownListNavRules = new Map([
	[
		InputNavigationAction.UP,
		(context: FocusContextProvider) => {
			context.focusPrevious();
			return true;
		},
	],
	[
		InputNavigationAction.DOWN,
		(context: FocusContextProvider) => {
			context.focusNext();
			return true;
		},
	],
	[InputNavigationAction.NONE, (context: FocusContextProvider) => context.focusCurrent()],
	[InputNavigationAction.NEXT, (context: FocusContextProvider) => context.focusCurrent()],
]) as FocusNavigationRulesMap;

export class DropDownContextProvider {
	private _selectedValue: Accessor<unknown>;
	private _setSelectedValue: Setter<unknown>;
	private _isEditing: Accessor<boolean>;
	private _setIsEditing: Setter<boolean>;

	constructor(defaultValue: unknown | undefined) {
		const [selectedValue, setSelectedValue] = createSignal<unknown>(defaultValue);
		const [isEditing, setIsEditing] = createSignal(false);
		this._selectedValue = selectedValue;
		this._setSelectedValue = setSelectedValue;
		this._isEditing = isEditing;
		this._setIsEditing = setIsEditing;
	}

	public get selectedValue() {
		return this._selectedValue;
	}

	public get isEditing() {
		return this._isEditing;
	}

	public setSelectedValue(value: unknown) {
		return this._setSelectedValue(value);
	}

	public setIsEditing(value: boolean | ((prev: boolean) => boolean)) {
		return this._setIsEditing(value);
	}
}

export const DropDownContext = createContext<DropDownContextProvider>();

export function useDropDownContext() {
	const context = useContext(DropDownContext);

	if (!context) {
		throw new Error("Unable to find context provider for DropDownContext");
	}

	return context;
}

export interface DropdownItemProps<T> {
	value: T;
	disabled?: boolean;
	class?: string;
}

export function DropdownItem<T>(props: ParentProps<DropdownItemProps<T>>) {
	const context = useDropDownContext();
	const value = createMemo(() => props.value);

	function selectItem() {
		context?.setSelectedValue(value());
	}

	const isSelected = createMemo(() => context.selectedValue() == value());

	return (
		<Activatable
			disabled={props.disabled}
			onActivate={selectItem}
			class={`group relative ${props.class ?? "p-2"}`}
		>
			<div
				class="absolute inset-0\.5 img-dropdown-focus opacity-0 group-focus\:opacity-70 group-hover\:opacity-70 group-pressed\:opacity-70 flex flex-row items-center justify-start"
				classList={{
					"opacity-30": isSelected(),
					"group-hover:opacity-100": !isSelected(),
				}}
			>
				<Show when={isSelected()}>
					<div class="mr-0\.5 rotate-180 img-selection-arrow" />
				</Show>
			</div>
			<div class="ml-3 relative">{props.children}</div>
		</Activatable>
	);
}

export interface Dropdown<T> {
	fallback?: JSX.Element;
	defaultValue?: T;
	selectedItemTemplate: (item: T) => JSX.Element;
	onItemSelected?: (value: T) => void;
	class?: string;
	disabled?: boolean;
	disableFocus?: boolean;
	onFocus?: () => void;
	hotkey?: string;
	autoFocus?: boolean;
	tabIndex?: number;
}

export function Dropdown<T>(props: ParentProps<Dropdown<T>>) {
	const context = new DropDownContextProvider(props.defaultValue);
	const audioTrigger = useAudio();
	const dropdownMount: Node | undefined = document.getElementById("uinext-dropdowns") ?? undefined;
	let ref!: HTMLDivElement;
	let popupRef!: HTMLDivElement;
	let activatableRef!: HTMLDivElement;
	const [dropdownMaxHeight, setDropdownMaxHeight] = createSignal<string | undefined>(undefined);
	const [dropdownWidth, setDropdownWidth] = createSignal<string | undefined>(undefined);
	const [dropdownTop, setDropdownTop] = createSignal<string | undefined>(undefined);
	const [dropdownLeft, setDropdownLeft] = createSignal<string | undefined>(undefined);
	const [openUp, setOpenUp] = createSignal(false);

	const selectionTemplate = createMemo(() => {
		const selectedItem = context.selectedValue() as T;
		const fallback = props.fallback ?? "Select An Item";
		return selectedItem ? props.selectedItemTemplate(selectedItem) : fallback;
	});

	const maxHeightPx = LayoutModel.get().toScaledPixels(512);

	let prevFocus: HTMLElement | undefined;

	createEffect(
		on(
			() => props.defaultValue,
			(value) => {
				if (value) {
					context.setSelectedValue(value);
				}
			},
		),
	);

	onMount(() => {
		window.addEventListener("click", handleClickOutside, true);
		window.addEventListener("touchstart", handleTouchOutside, true);
	});

	onCleanup(() => {
		window.removeEventListener("click", handleClickOutside, true);
		window.removeEventListener("touchstart", handleTouchOutside, true);
	});

	function triggerAudio() {
		if (context.isEditing()) {
			audioTrigger("Dropdown", "dropdown-open");
		} else {
			audioTrigger("Dropdown", "dropdown-close");
		}
	}

	function closeDropdown() {
		const shouldPlayAudio = context.isEditing();
		context.setIsEditing(false);

		if (shouldPlayAudio) {
			triggerAudio();
		}
	}

	// Close when a value is selected
	createEffect(
		on(
			() => context.selectedValue() as T,
			(value) => {
				closeDropdown();
				props.onItemSelected?.(value);
			},
		),
	);

	// Remember and restore previous focus
	createEffect(
		on(
			() => context.isEditing(),
			(isEditing) => {
				if (isEditing) {
					prevFocus = FocusManager.get().currentFocus();
				} else if (prevFocus) {
					FocusManager.get().setFocus(prevFocus);
					prevFocus = undefined;
				}
			},
		),
	);

	// Calculate how much space the dropdown can use before hitting the bottom of the screen
	createEffect(
		on(
			() => context.isEditing(),
			(isEditing) => {
				if (isEditing) {
					const rect = ref.getBoundingClientRect(); // Dropdown container.
					const availableHeightTop = rect.top;
					const availableHeightBottom = window.innerHeight - rect.bottom;

					// Determine if the dropdown should open upwards.
					const MARGIN = 4;
					setOpenUp(availableHeightTop > availableHeightBottom);
					if (openUp()) {
						// Bound max height to the space ABOVE dropdown.
						setDropdownMaxHeight(`${Math.min(availableHeightTop - MARGIN, maxHeightPx())}px`);
						setDropdownTop(`${rect.top}px`);
					} else {
						// Bound max height to the space BELOW dropdown.
						setDropdownMaxHeight(`${Math.min(availableHeightBottom - MARGIN, maxHeightPx())}px`);
						setDropdownTop(`${Math.max(rect.bottom, 0)}px`);
					}

					setDropdownLeft(`${Math.max(rect.left, 0)}px`);
					setDropdownWidth(`${Math.max(rect.width, 0)}px`);
				}
			},
		),
	);

	function toggleIfOutside(target: HTMLElement) {
		if (ref != target && !ref.contains(target) && popupRef != target && !popupRef?.contains(target)) {
			closeDropdown();
		}
	}

	function handleClickOutside(event: FocusEvent) {
		toggleIfOutside(event.target as HTMLElement);
	}

	function handleTouchOutside(event: TouchEvent) {
		toggleIfOutside(event.target as HTMLElement);
	}

	return (
		<div
			class={`dropdown__container relative border-2 border-primary-1 min-h-10 ${props.class ?? "min-w-76"}`}
			data-name="Dropdown"
			ref={ref}
		>
			<Activatable
				ref={activatableRef}
				onActivate={() => {
					context.setIsEditing((value) => !value);
					triggerAudio();
				}}
				on:blur={(event) => {
					handleClickOutside(event);
				}}
				disabled={props.disabled}
				disableFocus={props.disableFocus}
				onFocus={props.onFocus}
				data-name="dropdown-handle"
				class="relative flex flex-auto flex-row items-center justify-between group w-full"
				hotkeyAction={props.hotkey}
				autoFocus={props.autoFocus}
				tabIndex={props.tabIndex}
			>
				<div class="dropdown__bg absolute inset-px transition-opacity bg-primary-3" />
				<div class="dropdown__highlight absolute -inset-0\.5 fxs-dropdown-gradient img-dropdown-box-focus opacity-0 transition-opacity group-hover\:opacity-100 group-focus\:opacity-100 group-pressed\:opacity-100" />
				<div class="dropdown__label relative flex-auto">{selectionTemplate()}</div>
				<div
					class="dropdown__open-arrow min-w-8 min-h-12 -my-2 mr-1\.5 img-arrow transition-transform relative"
					classList={{
						disabled: props.disabled,
						"-rotate-90": context.isEditing() && !openUp(),
						"rotate-90": context.isEditing() && openUp(),
					}}
				/>
			</Activatable>

			<DropDownContext.Provider value={context}>
				<Show when={context.isEditing()}>
					<Portal mount={dropdownMount}>
						<Panel
							name="dropdown-panel"
							id="dropdown-panel"
							class="absolute z-1 img-dropdown-box flex flex-col pointer-events-none"
							ref={popupRef}
							style={{
								left: dropdownLeft(),
								width: dropdownWidth(),
								top: dropdownTop(),
								"max-height": dropdownMaxHeight(),
								// Transform directly applied rather than classList, as later drops merged properties on re-opening.
								transform: openUp() ? "translateY(-100%)" : undefined,
								"transform-origin": openUp() ? "bottom" : "top",
							}}
							onCancelInput={closeDropdown}
						>
							<ScrollArea class="flex-auto">
								<Slot
									class="flex flex-col"
									navRules={DropdownListNavRules}
								>
									{props.children}
								</Slot>
							</ScrollArea>
						</Panel>
					</Portal>
				</Show>
			</DropDownContext.Provider>
		</div>
	);
}
